package io.github.juliarezende521.workjourney.contract;
import io.github.juliarezende521.workjourney.account.*;import io.github.juliarezende521.workjourney.adjustment.*;import io.github.juliarezende521.workjourney.journey.marking.CurrentEmployeeIdentity;import io.github.juliarezende521.workjourney.journey.query.JourneyQueries.NotVisible;import io.github.juliarezende521.workjourney.time.UtcInstants;import java.time.*;import java.util.*;import org.springframework.context.annotation.Profile;import org.springframework.data.domain.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Profile("!bootstrap") class EmploymentContractService{
    private final CurrentEmployeeIdentity identity;private final EmployeeRepository employees;private final AppUserRepository users;private final EmploymentContractRepository contracts;private final AuditEntryRepository audits;private final Clock clock;
    EmploymentContractService(CurrentEmployeeIdentity identity,EmployeeRepository employees,AppUserRepository users,EmploymentContractRepository contracts,AuditEntryRepository audits,Clock clock){this.identity=identity;this.employees=employees;this.users=users;this.contracts=contracts;this.audits=audits;this.clock=clock;}
    @Transactional(readOnly=true) View currentForHr(UUID employeeId,LocalDate on){requireHr();var employee=employees.findActiveById(employeeId).orElseThrow(NotVisible::new);var date=on==null?UtcInstants.normalize(clock.instant()).atZone(ZoneId.of(employee.getReferenceTimeZoneId())).toLocalDate():on;return contracts.findFirstByEmployee_IdAndEffectiveFromLessThanEqualOrderByEffectiveFromDesc(employeeId,date).map(View::from).orElse(null);}
    @Transactional(readOnly=true) Page history(UUID employeeId,int page,int size){requireHr();validate(page,size);employees.findActiveById(employeeId).orElseThrow(NotVisible::new);var result=contracts.findByEmployee_Id(employeeId,PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"effectiveFrom","id")));return new Page(result.map(View::from).getContent(),page,size,result.getTotalElements());}
    @Transactional(timeout=15) View create(UUID employeeId,LocalDate from,String country,EmploymentContract.Type type,int weeklyMinutes){var actor=requireHr();var employee=employees.lockActive(employeeId).orElseThrow(NotVisible::new);if(contracts.existsByEmployee_IdAndEffectiveFrom(employeeId,from))throw new InvalidContract(409);var now=UtcInstants.normalize(clock.instant());var value=contracts.save(new EmploymentContract(employee,from,country,type,weeklyMinutes,actor.userId(),now));audits.save(new AuditEntry(actor.userId(),"EMPLOYMENT_CONTRACT_CREATED","EMPLOYMENT_CONTRACT",value.id(),now,"effectiveFrom="+from+",countryCode="+value.countryCode()+",employmentType="+type+",weeklyMinutes="+weeklyMinutes));return View.from(value);}
    private CurrentEmployeeIdentity.Identity requireHr(){var actor=identity.require();if(!users.existsByIdAndActiveTrueAndHrReaderTrue(actor.userId())||employees.findOwnedActive(actor.employeeId(),actor.userId()).isEmpty())throw new AccessDeniedException("HR access denied");return actor;}
    private void validate(int page,int size){if(page<0||page>Integer.MAX_VALUE/100||size<1||size>100)throw new InvalidContract();}
    record View(UUID id,UUID employeeId,LocalDate effectiveFrom,String countryCode,String employmentType,int weeklyMinutes,Instant createdAtUtc){static View from(EmploymentContract value){return new View(value.id(),value.employee().getId(),value.effectiveFrom(),value.countryCode(),value.type().name(),value.weeklyMinutes(),value.createdAt());}}
    record Page(List<View> items,int page,int size,long totalElements){}
}
